import { describe, expect, it } from 'vitest';
import { checkImage, checkVideo, findPageClaim, resolveOutcome } from '../src/index.js';

describe('findPageClaim', () => {
  it('finds a caption or alt text that says the item was made by AI', () => {
    for (const text of [
      'AI-generated image of a harbour at dusk',
      'Illustration generated by AI',
      'Image created with Midjourney',
      'Made with DALL-E 3',
      'Photo: via Stable Diffusion',
      'An A.I.-generated portrait',
      'This video was generated using Sora 2',
    ])
      expect(findPageClaim([text]), text).toMatchObject({ where: 'caption' });
  });

  it('does not take talk about AI for a statement about the item', () => {
    for (const text of [
      // Reported from real use: these were on an ordinary YouTube page.
      'AI-generated video summary',
      'AI can make mistakes, so double-check it.',
      'AI Slop Is Destroying The Internet',
      'AI',
      'Free AI image generator',
      'Is this AI-generated?',
      'This photo is not AI-generated',
      'AI-generated or real: can you tell',
      'Our AI-generated content policy',
      'AI-generated image detector',
      'Made with love in Lisbon',
      'Created by Maria Santos',
      'Generated in 2019 by the survey team',
    ])
      expect(findPageClaim([text]), text).toBeNull();
  });

  it('reads the tags uploaders put on their own AI posts, but not a bare #ai', () => {
    // Reported from real use: a YouTube Short titled like this.
    expect(findPageClaim(['Weird Ai Slop #aislop #ai #weird'])).toEqual({
      text: '#aislop',
      where: 'hashtag',
    });
    expect(findPageClaim(['New trailer #veo3 #shorts'])).toMatchObject({ text: '#veo3' });
    expect(findPageClaim(['My new tutorial #ai #coding'])).toBeNull();
    expect(findPageClaim(['Kingdom Hearts #sora #riku'])).toBeNull();
    expect(findPageClaim(['#aircraft #airshow'])).toBeNull();
  });

  it('reads a file name that says so', () => {
    // Reported from real use: pictures on an image generator's own site.
    expect(
      findPageClaim([], 'https://image-generator.com/assets/img/ai-generated-image-1.png'),
    ).toEqual({
      text: 'ai-generated-image-1.png',
      where: 'file name',
    });
    expect(findPageClaim([], 'https://cdn.example/made_with_ai_042.jpg')).toMatchObject({
      where: 'file name',
    });
    expect(findPageClaim([], 'https://cdn.example/ai-generated-content-policy.png')).toBeNull();
    expect(findPageClaim([], 'https://cdn.example/ai-generated/photo-of-minister.jpg')).toBeNull();
    expect(findPageClaim([], 'https://cdn.example/fair-generated-power.jpg')).toBeNull();
    expect(findPageClaim([], 'data:image/png;base64,ai-generated')).toBeNull();
  });
});

describe('what the page says, in the verdict', () => {
  const noBytes = new Uint8Array(0);

  it('gives "likely", never "made with AI", and quotes the words', async () => {
    const v = await checkImage({
      bytes: noBytes,
      nearbyLabels: ['AI-generated image of a harbour'],
    });
    expect(v.outcome).toBe('likely_ai');
    expect(v.reasons).toEqual(['page_says_ai']);
    expect(v.alert).toBe(false);
    expect(v.signals[0]).toMatchObject({
      kind: 'page_claim',
      details: { pageSays: 'AI-generated image of a harbour', saidIn: 'caption' },
    });
  });

  it('covers a picture the picture model refuses to judge', () => {
    // A painted AI picture: the gate keeps it out, but its file name says what it is.
    const v = resolveOutcome('image', [
      {
        status: 'assessed',
        signal: {
          detector: 'page.claim@test',
          modality: 'page',
          kind: 'page_claim',
          score: 1,
          reasons: ['page_says_ai'],
        },
      },
      { status: 'not_assessed', detector: 'image.classifier@test', reason: 'not_a_photo' },
    ]);
    expect(v).toMatchObject({ outcome: 'likely_ai', reasons: ['page_says_ai'] });
  });

  it('is outranked by a real label, and works for video tags', async () => {
    const labelled = await checkImage(
      { bytes: noBytes, nearbyLabels: ['AI info', 'AI-generated image'] },
      { hostname: 'www.facebook.com' },
    );
    expect(labelled.outcome).toBe('verified_ai');
    const video = await checkVideo({ nearbyLabels: ['Weird Ai Slop #aislop #ai #weird'] });
    expect(video).toMatchObject({ outcome: 'likely_ai', reasons: ['page_says_ai'] });
    const plain = await checkVideo({ nearbyLabels: ['Holiday in Crete #travel'] });
    expect(plain.outcome).toBe('not_assessed');
  });
});
